"""Deterministic local fixtures. Solidity embeds these bytes; tests never read the filesystem."""
import base64, hashlib, json, pathlib, struct, uuid, zlib
root = pathlib.Path(__file__).resolve().parent.parent
folder = root / 'test/fixtures'
def chunk(kind, payload):
    return struct.pack('>I', len(payload)) + kind + payload + struct.pack('>I', zlib.crc32(kind + payload))
png = b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', struct.pack('>IIBBBBB', 1, 1, 8, 6, 0, 0, 0)) + chunk(b'IDAT', zlib.compress(b'\x00\x2c\x58\xff\xff')) + chunk(b'IEND', b'')
html = b'<!doctype html><html><head><meta charset="utf-8"><style>body{color:#123}</style></head><body><h1 id="original-marker">Relay A1</h1><script>const marker="kept";</script></body></html>\n'
html3 = html.replace(b'</body>', b'<img alt="generated pixel" src="data:image/png;base64,' + base64.b64encode(png) + b'"></body>')
files = {'document.md': b'# Relay A1\n\nOriginal marker A1.\n', 'document-updated.md': b'# Relay A1\n\nOriginal marker A1.\n\nContinued explicitly.\n', 'html-1.html': html, 'image-2.png': png, 'html-3.html': html3}
project = str(uuid.uuid5(uuid.NAMESPACE_URL, 'https://example.invalid/a1/local-project'))
constants = []
for filename, content in files.items():
    (folder / filename).write_bytes(content)
    if filename.startswith('document'):
        name,path,mime='main','docs/main.md','text/markdown'
    elif filename.endswith('.png'):
        name,path,mime='illustration','assets/illustration.png','image/png'
    else:
        name,path,mime='site','dist/index.html','text/html'
    manifest = {'jobId': str(uuid.uuid5(uuid.NAMESPACE_URL, 'https://example.invalid/a1/'+filename)), 'projectId': project, 'state':'completed', 'launch':None, 'delivery':{'repoUrl':'https://example.invalid/local-fixture','commit':'local-fixture'}, 'source':[], 'files':[{'name':name,'path':path,'hash':hashlib.sha256(content).hexdigest(),'mediaType':mime,'bytes':len(content),'submissionHash':hashlib.sha256(('local-submission:'+filename).encode()).hexdigest()}]}
    raw = json.dumps(manifest, separators=(',',':'), ensure_ascii=False).encode()
    (folder/(filename+'.result.json')).write_bytes(raw)
    method = {'document.md':'document','document-updated.md':'documentUpdated','html-1.html':'htmlFirst','image-2.png':'imageSecond','html-3.html':'htmlThird'}[filename]
    constants.append(f'    function {method}() internal pure returns (bytes memory) {{ return hex"{content.hex()}"; }}')
    constants.append(f'    function {method}Result() internal pure returns (bytes memory) {{ return hex"{raw.hex()}"; }}')
(folder/'FixtureData.sol').write_text('// SPDX-License-Identifier: MIT\npragma solidity 0.8.26;\n\n// Generated by tools/generate-fixtures.py from actual local file bytes.\nlibrary FixtureData {\n'+ '\n'.join(constants)+f'\n    function project() internal pure returns (string memory) {{ return "{project}"; }}\n    function imageBase64() internal pure returns (string memory) {{ return "{base64.b64encode(png).decode()}"; }}\n}}\n')
